const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const TARGET=process.env.TARGET_CSS,PARENT=process.env.PARENT_SHA;
const assert=(x,m)=>{if(!x)throw new Error(m)};
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[];}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t];}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context});}}depth+=o-c;while(stack.length&&depth<=stack[stack.length-1].depthBefore){const p=stack.pop();if(p.type==='rule')sel=null;}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d);}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)};}
const parent=cp.execFileSync('git',['show',`${PARENT}:${TARGET}`],{encoding:'utf8'}),p=parse(parent);
assert(p.declarations.length===273&&p.dead.length===73,`parent drift ${p.declarations.length}/${p.dead.length}`);
assert(new Set(p.dead.map(d=>d.selector)).size===17,'selector drift');
assert(p.dead.every(d=>d.context==='@media (max-width: 760px)'&&!d.important&&!d.winnerImportant&&d.winnerLine>d.line),'proof drift');
const finalNewline=/\r?\n$/.test(parent),lines=parent.split(/\r?\n/);if(finalNewline&&lines.at(-1)==='')lines.pop();
for(const d of [...p.dead].sort((a,b)=>b.line-a.line)){assert(lines[d.line-1]?.trim().startsWith(d.property+':'),'line mismatch '+d.line);lines.splice(d.line-1,1);}
const expected=lines.join('\n')+(finalNewline?'\n':''),actual=fs.readFileSync(TARGET,'utf8'),a=parse(actual);
assert(actual===expected,'permanent bytes differ from certified deletion candidate');
assert(a.declarations.length===200&&a.dead.length===0,`permanent target drift ${a.declarations.length}/${a.dead.length}`);
const hash=crypto.createHash('sha256').update(actual).digest('hex'),bytes=Buffer.byteLength(actual),blob=cp.execFileSync('git',['hash-object',TARGET],{encoding:'utf8'}).trim();
console.log(`PERMANENT CANDIDATE IDENTITY PASS|parent=273/73|selectors=17|target=200/0|delta=+0/-73|hash=${hash}|bytes=${bytes}|blob=${blob}|runtimeProofTransfer=exact-bytes`);
